param([string]$ApiUrl='https://assets.2734.store',[Parameter(Mandatory=$true)][string]$RegistrationToken)
$ErrorActionPreference='Stop';$RegistrationToken=$RegistrationToken.Trim();if([string]::IsNullOrWhiteSpace($RegistrationToken)-or $RegistrationToken-eq 'change-me'){throw 'A valid server AGENT_REGISTRATION_TOKEN is required.'};$name='AssetFlowAgent';$target=Join-Path $env:ProgramFiles 'AssetFlow\Agent';$data=Join-Path $env:ProgramData 'AssetFlow';New-Item -ItemType Directory -Force $target,$data,(Join-Path $target 'logs')|Out-Null;Copy-Item (Join-Path $PSScriptRoot '..\publish\*') $target -Recurse -Force;@{ApiUrl=$ApiUrl.Trim();RegistrationToken=$RegistrationToken;CollectionMinutes=60;UpdateCheckMinutes=5}|ConvertTo-Json|Set-Content (Join-Path $data 'agent.json') -Encoding UTF8;if(Get-Service $name -ErrorAction SilentlyContinue){Stop-Service $name -Force;sc.exe delete $name|Out-Null};New-Service -Name $name -BinaryPathName ('"'+(Join-Path $target 'AssetFlow.Agent.exe')+'"') -DisplayName 'AssetFlow IT Asset Agent' -StartupType Automatic;Start-Service $name;Write-Host 'AssetFlow Agent installed and started. Logs: '$target'\logs'
